{
  "name": "doc-desk",
  "version": "0.1.0",
  "description": "doc-desk Mod: Claude が質問票 JSON を open_form ツールに渡すと、ブラウザに一枚のフォームを出して人に答えてもらい、回答を【doc-desk 回答】の固定形にして Claude に届ける (waitSeconds 以内ならツールの結果として、過ぎれば user turn として)。書き上げた文書を open_review に渡すと、人が段落や文字列に付けた指摘を同じ固定形で届ける (指摘モード)。",
  "author": {
    "name": "agent-kit"
  },
  "userConfig": {
    "selfReview": {
      "type": "boolean",
      "title": "指摘の画面に Claude の候補を出す",
      "description": "open_review の中で、Claude が自分の文書の直しどころを 1 回だけ見つけ、指摘の画面に候補として出します。人は採用か却下を押すだけです。切ると候補を作りません (その分の費用もかかりません)。",
      "default": true
    },
    "liveView": {
      "type": "boolean",
      "title": "書いている文書をブラウザに流す (ライブ表示)",
      "description": "Claude が open_live を呼ぶと、文書を書いている間その文をブラウザに流し、読みながら付けた指摘をその場で Claude に届けます。切ると open_live は何もしません。",
      "default": true
    }
  }
}
